/**
 * AIAgent - Main thread interface for AI configuration and events
 *
 * Provides a Three.js-style API for adding sensors and intents to agents.
 * Extends EventDispatcher for AI event listening.
 * All methods support variadic arguments for convenience.
 *
 * **Usage**
 *
 * ```js
 * import { AIEvent } from '@three-blocks/pro';
 *
 * // Add single sensor
 * body.ai.addSensor(new VisionSensor({ fov: 90 }));
 *
 * // Add multiple sensors at once
 * body.ai.addSensor(
 *   new VisionSensor({ fov: 90 }),
 *   new DamageSensor()
 * );
 *
 * // Add intents with priority
 * body.ai.addIntent(
 *   new PatrolIntent({ waypoints: [...], priority: 20 }),
 *   new EngageIntent({ priority: 80 })
 * );
 *
 * // Enable AI
 * body.ai.enable();
 *
 * // Listen to AI events using constants
 * body.ai.addEventListener(AIEvent.FIRE, (event) => {
 *   createMuzzleFlash(event.origin);
 *   playSound('gunshot');
 * });
 *
 * body.ai.addEventListener(AIEvent.ENGAGE, (event) => {
 *   console.log('Engaging target at distance:', event.targetDistance);
 * });
 *
 * body.ai.addEventListener(AIEvent.TARGET_ACQUIRED, (event) => {
 *   console.log('Target spotted!');
 * });
 *
 * // Chaining
 * body.ai
 *   .addSensor(new VisionSensor({ fov: 90 }))
 *   .addIntent(new PatrolIntent({ waypoints: [...] }))
 *   .enable();
 * ```
 *
 * **Available Events (AIEvent constants)**
 *
 * | Constant | Event | Source | Payload |
 * |----------|-------|--------|---------|
 * | `AIEvent.ENGAGE` | `engage` | EngageIntent | `{ targetPosition, targetDistance }` |
 * | `AIEvent.FIRE` | `fire` | EngageIntent | `{ origin, direction, target }` |
 * | `AIEvent.PATROL` | `patrol` | PatrolIntent | `{ waypoint, waypointIndex }` |
 * | `AIEvent.WAYPOINT_REACHED` | `waypointReached` | PatrolIntent | `{ waypointIndex, waypoint, isLast }` |
 * | `AIEvent.TARGET_ACQUIRED` | `targetAcquired` | VisionSensor | `{ targetIndex, targetType, distance, position }` |
 * | `AIEvent.TARGET_LOST` | `targetLost` | VisionSensor | `{ lastPosition }` |
 * | `AIEvent.DAMAGED` | `damaged` | DamageSensor | `{ damage, direction, shooterIndex, shooterType }` |
 * | `AIEvent.INTENT_CHANGE` | `intentChange` | Coordinator | `{ previous, current }` |
 *
 * @module @three-blocks/pro/ai/AIAgent
 * @class AIAgent
 * @extends THREE.EventDispatcher
 * @short Main thread AI configuration interface with events
 * @category AI
 * @tags AI, Agent, Configuration, Events
 */
export class AIAgent {
    /**
     * Create a new AIAgent.
     *
     * @param {KinematicBody} kinematicBody - Parent kinematic body.
     */
    constructor(kinematicBody: KinematicBody);
    /**
     * @type {KinematicBody}
     * @private
     */
    private _kinematicBody;
    /**
     * @type {Object}
     * @private
     */
    private _physics;
    /**
     * @type {number}
     * @private
     */
    private _bodyIndex;
    /**
     * @type {boolean}
     * @private
     */
    private _enabled;
    /**
     * Registered sensors (for local tracking).
     * @type {Map<string, Object>}
     * @private
     */
    private _sensors;
    /**
     * Registered intents (for local tracking).
     * @type {Map<string, Object>}
     * @private
     */
    private _intents;
    /**
     * Add one or more sensors to this agent.
     *
     * @param {...Sensor} sensors - Sensors to add.
     * @returns {AIAgent} This instance for chaining.
     *
     * @example
     * // Add single sensor
     * body.ai.addSensor(new VisionSensor({ fov: 90, range: 30 }));
     *
     * // Add multiple sensors
     * body.ai.addSensor(
     *   new VisionSensor({ fov: 90 }),
     *   new DamageSensor()
     * );
     */
    addSensor(...sensors: Sensor[]): AIAgent;
    /**
     * Add one or more intents to this agent.
     *
     * @param {...Intent} intents - Intents to add.
     * @returns {AIAgent} This instance for chaining.
     *
     * @example
     * // Add single intent
     * body.ai.addIntent(new PatrolIntent({ waypoints: [...] }));
     *
     * // Add multiple intents with priorities
     * body.ai.addIntent(
     *   new PatrolIntent({ waypoints: [...], priority: 20 }),
     *   new EngageIntent({ priority: 80 })
     * );
     */
    addIntent(...intents: Intent[]): AIAgent;
    /**
     * Remove a sensor from this agent.
     *
     * @param {Sensor} sensor - Sensor to remove.
     * @returns {AIAgent} This instance for chaining.
     */
    removeSensor(sensor: Sensor): AIAgent;
    /**
     * Remove an intent from this agent.
     *
     * @param {Intent} intent - Intent to remove.
     * @returns {AIAgent} This instance for chaining.
     */
    removeIntent(intent: Intent): AIAgent;
    /**
     * Enable AI control for this agent.
     *
     * @returns {AIAgent} This instance for chaining.
     */
    enable(): AIAgent;
    /**
     * Disable AI control for this agent.
     *
     * @returns {AIAgent} This instance for chaining.
     */
    disable(): AIAgent;
    /**
     * Check if AI is enabled.
     *
     * @returns {boolean} True if enabled.
     */
    get enabled(): boolean;
    /**
     * Get the current active intent name.
     * Note: This is read from local state; worker state may differ slightly.
     *
     * @returns {string} Active intent type or 'idle'.
     */
    get currentIntent(): string;
    /**
     * Get sensor count.
     *
     * @returns {number} Number of registered sensors.
     */
    get sensorCount(): number;
    /**
     * Get intent count.
     *
     * @returns {number} Number of registered intents.
     */
    get intentCount(): number;
    /**
     * Configure the coordinator.
     *
     * @param {Object} config - Coordinator configuration.
     * @param {number} [config.hysteresisThreshold] - Priority difference to switch.
     * @returns {AIAgent} This instance for chaining.
     */
    setCoordinatorConfig(config: {
        hysteresisThreshold?: number;
    }): AIAgent;
    /**
     * Send configuration update to physics worker.
     *
     * @param {Object} config - Configuration to send.
     * @private
     */
    private _syncToWorker;
    /**
     * Dispose of the AI agent.
     */
    dispose(): void;
}
